WITH base AS (SELECT id, session_id, event_type, page, duration_sec, ROUND(duration_sec * 100, 2) duration_sec_scaled, COALESCE(page, 'DIRECT') resolved_page FROM web_events WHERE event_time > DATE '2024-05-05' AND page IS NOT NULL), latest AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY session_id, page ORDER BY duration_sec_scaled) AS row_num FROM base) ranked WHERE row_num = 1), base_web_events AS (SELECT id, session_id, event_type, duration_sec, resolved_page, row_num, LEAST(duration_sec_scaled, row_num) least_duration_sec_scaled_row_num, CAST(row_num AS DOUBLE) row_num_num FROM latest WHERE page IS NOT NULL), with_dims AS (SELECT src.*, d.browser, d.country FROM base_web_events src LEFT JOIN sessions d ON src.session_id = d.id), enriched AS (SELECT src.*, p.country AS session_country, p.device FROM with_dims src INNER JOIN sessions p ON src.session_id = p.id), matched_keys AS (SELECT session_id, event_type FROM enriched EXCEPT DISTINCT SELECT session_id, event_type FROM web_events WHERE event_time < '2025-03-01'), verified AS (SELECT s.* FROM enriched s INNER JOIN matched_keys k ON s.session_id = k.session_id AND s.event_type = k.event_type), scored AS (SELECT *, SUM(least_duration_sec_scaled_row_num) OVER (PARTITION BY browser) browser_sum_least_duration_sec_scaled_row_num, CUME_DIST() OVER (PARTITION BY session_country ORDER BY duration_sec DESC NULLS LAST) duration_sec_cume_dist, RANK() OVER w_recent row_num_num_rank FROM verified WINDOW w_recent AS (ORDER BY row_num_num DESC NULLS LAST)) SELECT device, CASE WHEN duration_sec_cume_dist >= 0.72 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_cume_dist_tier, CASE WHEN least_duration_sec_scaled_row_num >= 89 THEN 'HIGH' ELSE 'LOW' END AS least_duration_sec_scaled_row_num_tier, COUNT(*) FILTER (WHERE device = 'desktop') AS desktop_rows, SIZE(COLLECT_SET(device)) AS num_devices, BIT_AND(duration_sec) AS duration_sec_bit_and, COUNT(*) AS row_count, GROUPING(device) AS grouping_level FROM scored GROUP BY GROUPING SETS ((device, CASE WHEN duration_sec_cume_dist >= 0.72 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN least_duration_sec_scaled_row_num >= 89 THEN 'HIGH' ELSE 'LOW' END), (device, CASE WHEN duration_sec_cume_dist >= 0.72 THEN 'PREMIUM' ELSE 'STANDARD' END), (device), ())
